class CostTracker:
    """Per-provider cost tracking with multi-dimensional aggregation.

    Inspired by Paperclip's cost tracking with 6 aggregation dimensions.
    """

    # Rough per-1K-token costs (USD). Can be overridden per provider/model.
    DEFAULT_COSTS: dict[str, dict[str, float]] = {
        "openai": {"input": 0.0025, "output": 0.01},
        "anthropic": {"input": 0.003, "output": 0.015},
        "gemini": {"input": 0.00125, "output": 0.005},
        "ollama": {"input": 0.0, "output": 0.0},
        "litellm": {"input": 0.0025, "output": 0.01},
    }

    def __init__(self) -> None:
        self._events: list[CostEvent] = []
        self._cost_overrides: dict[str, dict[str, float]] = {}

    def set_cost_per_1k(self, provider: str, input_cost: float, output_cost: float) -> None:
        self._cost_overrides[provider] = {"input": input_cost, "output": output_cost}

    def record(self, event: CostEvent) -> None:
        if event.cost_usd == 0.0:
            rates = self._cost_overrides.get(event.provider, self.DEFAULT_COSTS.get(event.provider, {"input": 0.0, "output": 0.0}))
            event.cost_usd = (
                (event.input_tokens / 1000.0) * rates.get("input", 0.0)
                + (event.output_tokens / 1000.0) * rates.get("output", 0.0)
            )
        self._events.append(event)

    def summary(self) -> dict[str, Any]:
        if not self._events:
            return {"total_cost_usd": 0.0, "total_tokens": 0, "event_count": 0}
        return {
            "total_cost_usd": sum(e.cost_usd for e in self._events),
            "total_tokens": sum(e.total_tokens for e in self._events),
            "total_input_tokens": sum(e.input_tokens for e in self._events),
            "total_output_tokens": sum(e.output_tokens for e in self._events),
            "event_count": len(self._events),
        }

    def by_provider(self) -> dict[str, dict[str, Any]]:
        result: dict[str, dict[str, Any]] = {}
        for e in self._events:
            if e.provider not in result:
                result[e.provider] = {"cost_usd": 0.0, "input_tokens": 0, "output_tokens": 0, "calls": 0}
            r = result[e.provider]
            r["cost_usd"] += e.cost_usd
            r["input_tokens"] += e.input_tokens
            r["output_tokens"] += e.output_tokens
            r["calls"] += 1
        return result

    def by_stage(self) -> dict[str, dict[str, Any]]:
        result: dict[str, dict[str, Any]] = {}
        for e in self._events:
            stage = e.stage or "unspecified"
            if stage not in result:
                result[stage] = {"cost_usd": 0.0, "input_tokens": 0, "output_tokens": 0, "calls": 0}
            r = result[stage]
            r["cost_usd"] += e.cost_usd
            r["input_tokens"] += e.input_tokens
            r["output_tokens"] += e.output_tokens
            r["calls"] += 1
        return result

    def by_model(self) -> dict[str, dict[str, Any]]:
        result: dict[str, dict[str, Any]] = {}
        for e in self._events:
            key = f"{e.provider}/{e.model}"
            if key not in result:
                result[key] = {"cost_usd": 0.0, "input_tokens": 0, "output_tokens": 0, "calls": 0}
            r = result[key]
            r["cost_usd"] += e.cost_usd
            r["input_tokens"] += e.input_tokens
            r["output_tokens"] += e.output_tokens
            r["calls"] += 1
        return result

    def reset(self) -> None:
        self._events.clear()

    def events_in_range(self, start: float, end: float) -> list:
        """Return cost events whose timestamp falls within [start, end] epoch seconds."""
        return [
            e for e in self._events
            if start <= e.timestamp.timestamp() <= end
        ]

    def persist(self, path: str) -> None:
        """Write all cost events to a JSONL file."""
        from pathlib import Path
        Path(path).parent.mkdir(parents=True, exist_ok=True)
        with open(path, "w", encoding="utf-8") as f:
            for e in self._events:
                line = json.dumps({
                    "provider": e.provider,
                    "model": e.model,
                    "input_tokens": e.input_tokens,
                    "output_tokens": e.output_tokens,
                    "cost_usd": e.cost_usd,
                    "stage": e.stage,
                    "run_id": e.run_id,
                    "timestamp": e.timestamp.isoformat(),
                })
                f.write(line + "\n")

    @classmethod
    def load(cls, path: str) -> "CostTracker":
        """Load cost events from a JSONL file."""
        tracker = cls()
        from backend.providers.base import CostEvent
        from datetime import datetime, timezone
        with open(path, encoding="utf-8") as f:
            for line in f:
                data = json.loads(line.strip())
                event = CostEvent(
                    provider=data["provider"],
                    model=data["model"],
                    input_tokens=data["input_tokens"],
                    output_tokens=data["output_tokens"],
                    cost_usd=data.get("cost_usd", 0.0),
                    stage=data.get("stage", ""),
                    run_id=data.get("run_id"),
                    timestamp=datetime.fromisoformat(data.get("timestamp", datetime.now(timezone.utc).isoformat())),
                )
                tracker._events.append(event)
        return tracker

"""Model selection: maps pipeline task types to appropriate providers.

Thinking tasks (classification, extraction, ranking) use a fast, cheap model.
Generation tasks (writing, synthesis, critique) use a powerful model.
When no model split is configured, both resolve to the default provider.
"""
from __future__ import annotations

import logging
from typing import Any

logger = logging.getLogger(__name__)

# Task type classifications
THINKING_TASKS = frozenset({
    "classify", "extract", "rank", "filter", "dedup",
    "embedding", "cluster", "score", "evaluate",
})

GENERATION_TASKS = frozenset({
    "generate", "synthesize", "write", "critique",
    "ideate", "refine", "propose", "summarize",
})


class ModelSelector:
    """Maps task types to the appropriate LLM provider.

    Uses the thinking/generation model split when configured,
    falls back to the default provider otherwise.
    """

    def __init__(self, settings: Any = None) -> None:
        self._settings = settings
        self._thinking_provider = None
        self._generation_provider = None

    def resolve(self, task_type: str) -> Any:
        """Resolve the appropriate provider for a task type.

        Args:
            task_type: One of the task types in THINKING_TASKS or GENERATION_TASKS.
                       Unknown types default to the generation provider.

        Returns:
            LLM provider instance.
        """
        if task_type in THINKING_TASKS:
            return self._get_thinking()
        # Default: generation provider for all generation tasks and unknowns
        return self._get_generation()

    def _get_thinking(self) -> Any:
        if self._thinking_provider is None:
            from backend.providers.provider_factory import get_thinking_provider
            self._thinking_provider = get_thinking_provider(self._settings)
            logger.debug("Resolved thinking provider: %s", type(self._thinking_provider).__name__)
        return self._thinking_provider

    def _get_generation(self) -> Any:
        if self._generation_provider is None:
            from backend.providers.provider_factory import get_generation_provider
            self._generation_provider = get_generation_provider(self._settings)
            logger.debug("Resolved generation provider: %s", type(self._generation_provider).__name__)
        return self._generation_provider

    @staticmethod
    def is_thinking_task(task_type: str) -> bool:
        """Check if a task type is classified as a thinking task."""
        return task_type in THINKING_TASKS

    @staticmethod
    def is_generation_task(task_type: str) -> bool:
        """Check if a task type is classified as a generation task."""
        return task_type in GENERATION_TASKS

